if (!defined('ABSPATH')) exit;

function artisanskart_theme_setup() {
    add_theme_support('title-tag');
    add_theme_support('post-thumbnails');
    add_theme_support('custom-logo');
    add_theme_support('html5', ['search-form', 'comment-form', 'comment-list', 'gallery', 'caption', 'style', 'script']);
}
add_action('after_setup_theme', 'artisanskart_theme_setup');

function artisanskart_enqueue_scripts() {
    wp_enqueue_style('artisanskart-fonts', 'https://fonts.googleapis.com/css2?family=Kanit:wght@300;400;500;600;700;800;900&display=swap', [], null);
    wp_enqueue_style('artisanskart-main-style', get_stylesheet_uri(), [], '2.0.0');
}
add_action('wp_enqueue_scripts', 'artisanskart_enqueue_scripts');
